function (startTime, durationInput, blocked) {
  const input = AvailabilityChecker.validateInput(startTime, durationInput);
  if (!input.valid) {
    return AvailabilityChecker.createResult(false, input.reasonCode, input.message, input.endTime);
  }
  if (blocked) {
    return AvailabilityChecker.createResult(false, "ROOM_BLOCKED", "Room is blocked.", input.endTime);
  }
  const overlapping = AvailabilityChecker.bookings.filter(booking => input.start < booking.end && booking.start < input.end);
  if (overlapping.length > 0) {
    const intervals = overlapping.map(booking => AvailabilityChecker.formatTime(booking.start) + "–" + AvailabilityChecker.formatTime(booking.end)).join(", ");
    return AvailabilityChecker.createResult(false, "OVERLAP", "Overlaps existing booking(s): " + intervals, input.endTime);
  }
  return AvailabilityChecker.createResult(true, "AVAILABLE", "Room is available for the selected interval.", input.endTime);
}

