export default {
  currentTime: 720,
  maxDuration: 120,

  bookings: [
    {
      id: "b1",
      start: 540,
      end: 600,
      bookedBy: "Dr. Chen",
      purpose: "Faculty Meeting"
    },
    {
      id: "b2",
      start: 780,
      end: 840,
      bookedBy: "CS Club",
      purpose: "Workshop"
    },
    {
      id: "b3",
      start: 1020,
      end: 1080,
      bookedBy: "Study Group",
      purpose: "Review Session"
    }
  ],

  // Format minutes as HH:MM
  formatTime(minutes) {
    if (
      !Number.isInteger(minutes) ||
      minutes < 0 ||
      minutes > 1440
    ) {
      return "--:--";
    }

    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;

    return String(hours).padStart(2, "0") +
      ":" + String(mins).padStart(2, "0");
  },

  // Prepare read-only booking table data
  getBookings() {
    return this.bookings.map(booking => ({
      ID: booking.id,
      Start: this.formatTime(booking.start),
      End: this.formatTime(booking.end),
      "Booked By": booking.bookedBy,
      Purpose: booking.purpose
    }));
  },

  // Create a structured result
  createResult(available, reasonCode, message, endTime = "--:--") {
    const validationCodes = [
      "INVALID_TIME",
      "INVALID_INTERVAL",
      "PAST_START",
      "DURATION_LIMIT"
    ];

    return {
      available,
      reasonCode,
      message,
      endTime,
      status: available
        ? "Available"
        : validationCodes.includes(reasonCode)
          ? "Validation Error"
          : "Unavailable"
    };
  },

  // Validate and normalize user inputs
  validateInput(startTime, durationInput) {
    const time = String(startTime ?? "").trim();
    const durationText = String(durationInput ?? "").trim();

    const validTime = /^(?:[01]\d|2[0-3]):[0-5]\d$/.test(time);
    const duration = Number(durationText);

    if (
      !validTime ||
      !/^-?\d+$/.test(durationText) ||
      !Number.isFinite(duration) ||
      !Number.isInteger(duration)
    ) {
      return {
        valid: false,
        reasonCode: "INVALID_TIME",
        message: "Enter a valid start time and whole-number duration.",
        endTime: "--:--"
      };
    }

    const [hours, minutes] = time.split(":").map(Number);
    const start = hours * 60 + minutes;
    const end = start + duration;
    const endTime = this.formatTime(end);

    if (duration <= 0 || end > 1440) {
      return {
        valid: false,
        reasonCode: "INVALID_INTERVAL",
        message: "Duration must be positive and the interval must remain within the same day.",
        endTime
      };
    }

    if (start <= this.currentTime) {
      return {
        valid: false,
        reasonCode: "PAST_START",
        message: "Start time must be after the current time.",
        endTime
      };
    }

    if (duration > this.maxDuration) {
      return {
        valid: false,
        reasonCode: "DURATION_LIMIT",
        message: "Booking cannot be longer than 120 minutes.",
        endTime
      };
    }

    return {
      valid: true,
      start,
      end,
      duration,
      endTime
    };
  },

  // Calculate availability
  checkAvailability(startTime, durationInput, blocked) {
    const input = this.validateInput(startTime, durationInput);

    if (!input.valid) {
      return this.createResult(
        false,
        input.reasonCode,
        input.message,
        input.endTime
      );
    }

    if (blocked) {
      return this.createResult(
        false,
        "ROOM_BLOCKED",
        "Room is blocked.",
        input.endTime
      );
    }

    const overlapping = this.bookings.filter(booking =>
      input.start < booking.end &&
      booking.start < input.end
    );

    if (overlapping.length > 0) {
      const intervals = overlapping.map(booking =>
        this.formatTime(booking.start) +
        "–" +
        this.formatTime(booking.end)
      ).join(", ");

      return this.createResult(
        false,
        "OVERLAP",
        "Overlaps existing booking(s): " + intervals,
        input.endTime
      );
    }

    return this.createResult(
      true,
      "AVAILABLE",
      "Room is available for the selected interval.",
      input.endTime
    );
  },

  // Execute the workflow using widget values
  async runCheck() {
    const result = this.checkAvailability(
      StartTimeInput.text,
      DurationInput.text,
      BlockedSwitch.isSwitchedOn
    );

    await storeValue("availabilityResult", result, false);

    return result;
  },

	  testImmutability() {
    const before = JSON.stringify(this.bookings);

    const testCases = [
      ["15:00", "60", false],
      ["13:30", "60", false],
      ["15:00", "60", true],
      ["15:00", "0", false],
      ["14:30", "121", false],
      ["11:00", "30", false],
      ["14:00", "60", false]
    ];

    testCases.forEach(([start, duration, blocked]) => {
      this.checkAvailability(start, duration, blocked);
    });

    const after = JSON.stringify(this.bookings);

    return {
      test: "T8 - Booking Data Immutability",
      checksExecuted: testCases.length,
      passed: before === after,
      before: JSON.parse(before),
      after: JSON.parse(after)
    };
  }

};

